NATL_WORKDAY_ACC_GL_FILE_LOAD_PROC.source_lines:
exception
when others then
	dbms_output.put_line('Error in loading data in main table: ' || SQLERRM);

IF V_COUNT != 0 THEN
    BEGIN
    n_file_name:= TO_CHAR(SYSDATE, 'YYYYMMDD_HH24:MI:SS')||'_'||p_file_name;
    utl_file.fcopy (
       l_file_dir,
        p_file_name,
       l_dir_arc,
       n_file_name);
    NATL_WORKDAY_PAY_GL_DATA_PKG.NATL_WORKDAY_PAY_GL_DATA_PRC(v_file_name);
    END;

ELSE
    dbms_output.put_line('No data loaded in Main table');
    UPDATE NCRNICSERPCSPPRC.NATL_WORKDAY_CLOUD_GL_FILE_STATUS
	SET STATUS = 'E'
	where file_name = p_file_name;
	commit;

UPDATE NCRNICSERPCSPPRC.NATL_WORKDAY_CLOUD_GL_FILE_STATUS
SET STATUS = 'P'
where file_name = p_file_name;
commit;

exception
when others then
	dbms_output.put_line('Error : '||SQLERRM);
	dbms_output.put_line('Send Email Start');
	ncr_common_utility_pkg.send_mail(pi_process=> 'NCR_GL_JOURNALS_INTERFACE',
                                     pi_event  => 'VALIDATION_FAIL',
                                     pi_subject=> 'Issue in Workday Payroll GL File',
                                     pi_message=> 'Error at :'||v_Stage, ... );
